content:
:root {
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --bg-color: #f3f4f6;
  --card-bg: #ffffff;
  --text-color: #1f2937;
  --text-light: #6b7280;
  --border-color: #e5e7eb;
  --success-color: #10b981;
  --error-color: #ef4444;
}

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-color);
  -webkit-font-smoothing: antialiased;
}

.app-container {
  max-width: 600px;
  margin: 40px auto;
  padding: 20px;
  box-sizing: border-box;
}

.header {
  text-align: center;
  margin-bottom: 30px;
}

.header h1 {
  font-size: 2rem;
  color: var(--text-color);
  margin-bottom: 8px;
}

.header p {
  color: var(--text-light);
  font-size: 1rem;
}

.quiz-card {
  background-color: var(--card-bg);
  border-radius: 12px;
  padding: 24px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  margin-bottom: 20px;
}

.progress-bar {
  height: 8px;
  background-color: var(--border-color);
  border-radius: 4px;
  margin-bottom: 20px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background-color: var(--primary-color);
  transition: width 0.3s ease;
}

.options-container {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 20px;
}

.option-btn {
  background-color: #f9fafb;
  border: 2px solid var(--border-color);
  border-radius: 8px;
  padding: 14px 16px;
  font-size: 1rem;
  text-align: left;
  cursor: pointer;
  transition: all 0.2s ease;
  color: var(--text-color);
}

.option-btn:hover:not(:disabled) {
  background-color: #f3f4f6;
  border-color: var(--primary-color);
}

.option-btn.correct {
  background-color: #d1fae5;
  border-color: var(--success-color);
  color: #065f46;
}

.option-btn.incorrect {
  background-color: #fee2e2;
  border-color: var(--error-color);
  color: #991b1b;
}

.option-btn:disabled {
  cursor: default;
}

.explanation {
  margin-top: 20px;
  padding: 16px;
  background-color: #eff6ff;
  border-left: 4px solid var(--primary-color);
  border-radius: 0 8px 8px 0;
  font-size: 0.95rem;
  line-height: 1.5;
}

.btn {
  display: inline-block;
  font-weight: 500;
  text-align: center;
  white-space: nowrap;
  vertical-align: middle;
  user-select: none;
  border: 1px solid transparent;
  padding: 10px 20px;
  font-size: 1rem;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.2s ease;
}

.btn-primary {
  background-color: var(--primary-color);
  color: white;
  width: 100%;
  margin-top: 20px;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.score-card {
  text-align: center;
  background-color: var(--card-bg);
  border-radius: 12px;
  padding: 40px 24px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
}

.score-card h2 {
  font-size: 1.8rem;
  margin-bottom: 16px;
}

.score-card p {
  font-size: 1.2rem;
  color: var(--text-light);
  margin-bottom: 24px;
}

@media (max-width: 480px) {
  .app-container {
    margin: 10px;
    padding: 10px;
  }
  .quiz-card {
    padding: 16px;
  }
}

export interface QuizQuestion {
  id: number;
  question: string;
  options: string[];
  correctAnswer: number;
  explanation: string;
}

export interface QuizState {
  currentQuestionIndex: number;
  score: number;
  selectedOption: number | null;
  isAnswered: boolean;
  isFinished: boolean;
  userAnswers: number[];
}

import { useState } from 'react';
import { QuizQuestion, QuizState } from './types';

const questions: QuizQuestion[] = [
  {
    id: 1,
    question: "日本で一番面積が大きい都道府県はどこ？",
    options: ["北海道", "岩手県", "福島県", "長野県"],
    correctAnswer: 0,
    explanation: "北海道は日本の都道府県の中で最も面積が大きく、日本の総面積の約22%を占めています。"
  },
  {
    id: 2,
    question: "日本最西端に位置する島はどこ？",
    options: ["与那国島", "沖ノ鳥島", "南鳥島", "択捉島"],
    correctAnswer: 0,
    explanation: "沖縄県にある与那国島が日本最西端の島です。"
  },
  {
    id: 3,
    question: "日本最大の湖である「琵琶湖」がある都道府県はどこ？",
    options: ["京都府", "大阪府", "滋賀県", "三重県"],
    correctAnswer: 2,
    explanation: "琵琶湖は滋賀県に位置し、県土の約6割を占める日本最大の湖です。"
  },
  {
    id: 4,
    question: "日本で一番長さ（全長）がある川はどれ？",
    options: ["利根川", "信濃川", "石狩川", "四万十川"],
    correctAnswer: 1,
    explanation: "信濃川は長野県から新潟県を流れ、全長367kmで日本一長い川です。"
  },
  {
    id: 5,
    question: "次のうち、政令指定都市ではない都市はどこ？",
    options: ["川崎市", "浜松市", "高松市", "新潟市"],
    correctAnswer: 2,
    explanation: "高松市は香川県の県庁所在地ですが、政令指定都市ではありません。"
  }
];

export default function App() {
  const [state, setState] = useState<QuizState>({
    currentQuestionIndex: 0,
    score: 0,
    selectedOption: null,
    isAnswered: false,
    isFinished: false,
    userAnswers: []
  });

  const currentQuestion = questions[state.currentQuestionIndex];

  const handleSelectOption = (index: number) => {
    if (state.isAnswered) return;

    const isCorrect = index === currentQuestion.correctAnswer;
    setState(prev => ({
      ...prev,
      selectedOption: index,
      isAnswered: true,
      score: isCorrect ? prev.score + 1 : prev.score,
      userAnswers: [...prev.userAnswers, index]
    }));
  };

  const handleNextQuestion = () => {
    if (state.currentQuestionIndex + 1 < questions.length) {
      setState(prev => ({
        ...prev,
        currentQuestionIndex: prev.currentQuestionIndex + 1,
        selectedOption: null,
        isAnswered: false
      }));
    } else {
      setState(prev => ({
        ...prev,
        isFinished: true
      }));
    }
  };

  const handleRestart = () => {
    setState({
      currentQuestionIndex: 0,
      score: 0,
      selectedOption: null,
      isAnswered: false,
      isFinished: false,
      userAnswers: []
    });
  };

  return (
    <div className="app-container">
      <div className="header">
        <h1>日本の地理クイズ</h1>
        <p>日本の地理に関する知識を試そう！全5問</p>
      </div>

      {!state.isFinished ? (
        <div className="quiz-card">
          <div className="progress-bar">
            <div 
              className="progress-fill" 
              style={{ width: `${((state.currentQuestionIndex + 1) / questions.length) * 100}%` }}
            />
          </div>
          <p style={{ color: "var(--text-light)", marginBottom: "8px" }}>
            第 {state.currentQuestionIndex + 1} 問 / 全 {questions.length} 問
          </p>
          <h2 style={{ fontSize: "1.25rem", marginBottom: "20px" }}>
            {currentQuestion.question}
          </h2>

          <div className="options-container">
            {currentQuestion.options.map((option, index) => {
              let btnClass = "option-btn";
              if (state.isAnswered) {
                if (index === currentQuestion.correctAnswer) {
                  btnClass += " correct";
                } else if (index === state.selectedOption) {
                  btnClass += " incorrect";
                }
              }

              return (
                <button
                  key={index}
                  className={btnClass}
                  onClick={() => handleSelectOption(index)}
                  disabled={state.isAnswered}
                >
                  {option}
                </button>
              );
            })}
          </div>

          {state.isAnswered && (
            <div>
              <div className="explanation">
                <strong>解説:</strong> {currentQuestion.explanation}
              </div>
              <button className="btn btn-primary" onClick={handleNextQuestion}>
                {state.currentQuestionIndex + 1 < questions.length ? "次の問題へ" : "結果を見る"}
              </button>
            </div>
          )}
        </div>
      ) : (
        <div className="score-card">
          <h2>クイズ終了！</h2>
          <p>正解数: <strong>{state.score}</strong> / {questions.length}</p>
          <p>
            {state.score === questions.length 
              ? "おめでとうございます！パーフェクトです！" 
              : state.score >= 3 
              ? "よくできました！地理マスターまであと少し！" 
              : "もう少しがんばりましょう！"}
          </p>
          <button className="btn btn-primary" onClick={handleRestart}>
            もう一度挑戦する
          </button>
        </div>
      )}
    </div>
  );
}
